import { MODULE_ID } from "../constants/General.mjs";

const DISABLE_NOTIFICATIONS_TAG = "disable-notifications";

/**
 * Notifications shown by the token bar. A host module that registers a "disable-notifications"
 * world or client setting under its own id lets users silence them; without that setting every
 * notification is shown.
 * @module utils/NotifyUtil
 */
export class NotifyUtil {
  /**
   * @param {string} message
   * @param {Object} [options] - Options passed to Foundry's notifications
   */
  static info(message, options) {
    if (this.#muted()) return;
    ui.notifications.info(message, options);
  }

  /**
   * @param {string} message
   * @param {Object} [options]
   */
  static warn(message, options) {
    if (this.#muted()) return;
    ui.notifications.warn(message, options);
  }

  /**
   * @param {string} message
   * @param {Object} [options]
   */
  static error(message, options) {
    if (this.#muted()) return;
    ui.notifications.error(message, options);
  }

  /**
   * Whether the host's disable-notifications setting is on
   * @returns {boolean}
   */
  static #muted() {
    const key = `${MODULE_ID}.${DISABLE_NOTIFICATIONS_TAG}`;
    if (!game.settings?.settings?.has(key)) return false;
    try {
      return !!game.settings.get(MODULE_ID, DISABLE_NOTIFICATIONS_TAG);
    } catch (error) {
      return false;
    }
  }
}
