import { getSettings } from "../constants/Settings.mjs";
import { SettingsUtil } from "../utils/SettingsUtil.mjs";
import { LibWrapperUtil } from "../utils/LibWrapperUtil.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";

/**
 * Applies the "token movement speed" setting to token movement animations by wrapping
 * Token.prototype.animate, through libWrapper when available or a direct prototype patch otherwise.
 * @module tokens/TokenAnimationSpeed
 */
export class TokenAnimationSpeed {
  static #target = "foundry.canvas.placeables.Token.prototype.animate";
  static #initialized = false;

  /**
   * Install the animate wrapper once
   */
  static initialize() {
    if (this.#initialized) return;
    this.#initialized = true;

    const registered = LibWrapperUtil.register(
      this.#target,
      function (wrapped, to, options = {}, ...rest) {
        TokenAnimationSpeed.applyAnimateOptions(options);
        return wrapped(to, options, ...rest);
      },
      "WRAPPER"
    );
    if (registered) return;

    LogUtil.log("TokenAnimationSpeed: libWrapper unavailable, patching Token.prototype.animate");
    const TokenClass = foundry.canvas.placeables.Token;
    const originalAnimate = TokenClass.prototype.animate;
    TokenClass.prototype.animate = function (to, options = {}, ...rest) {
      TokenAnimationSpeed.applyAnimateOptions(options);
      return originalAnimate.call(this, to, options, ...rest);
    };
  }

  /**
   * Fill in the configured movement speed when the caller did not request one
   * @param {Object} options - Token animation options, mutated in place
   */
  static applyAnimateOptions(options) {
    if (options.movementSpeed) return;
    const speed = this.movementSpeed;
    if (speed !== null) options.movementSpeed = speed;
  }

  /**
   * Movement speed configured in the module settings, in grid spaces per second
   * @returns {number|null} The configured speed, or null when the setting is unset, zero or not a positive number
   */
  static get movementSpeed() {
    const speed = Number(SettingsUtil.get(getSettings().tokenMovementSpeed.tag));
    return Number.isFinite(speed) && speed > 0 ? speed : null;
  }
}
