import { LogUtil } from "../utils/LogUtil.mjs";

/**
 * Canvas side of teleport mode: ghost sprites following the cursor, click to place,
 * right-click / Escape to cancel. The controller passed to attach() supplies placements
 * and receives place / cancel calls.
 * @module tokens/TokenTeleportPreview
 */
export class TokenTeleportPreview {
  static #controller = null;
  static #handlers = null;
  static #escapeHandler = null;
  static #rightDownPosition = null;
  static #hasDragged = false;

  /**
   * Attach canvas listeners for teleport mode
   * @param {{isPerformingTeleport: function(): boolean, getPreviewPlacements: function({x: number, y: number}): Array, place: function({x: number, y: number}): Promise<void>, cancel: function(): void}} controller
   */
  static attach(controller) {
    this.detach();
    if (!canvas?.stage) {
      LogUtil.warn("TokenTeleportPreview: canvas stage not available");
      return;
    }
    this.#controller = controller;
    this.#handlers = {
      mousemove: event => this.#onMouseMove(event),
      click: event => this.#onClick(event),
      rightclick: event => this.#onRightClick(event),
      rightdown: event => this.#onRightDown(event),
      rightup: () => this.#onRightUp()
    };
    this.#escapeHandler = event => this.#onKeyDown(event);
    for (const [name, handler] of Object.entries(this.#handlers)) {
      canvas.stage.on(name, handler);
    }
    document.addEventListener("keydown", this.#escapeHandler);
    LogUtil.log("TokenTeleportPreview: handlers attached");
  }

  /**
   * Remove canvas listeners, keeping any drawn graphics
   */
  static detach() {
    if (this.#handlers) {
      for (const [name, handler] of Object.entries(this.#handlers)) {
        canvas?.stage?.off(name, handler);
      }
      this.#handlers = null;
    }
    if (this.#escapeHandler) {
      document.removeEventListener("keydown", this.#escapeHandler);
      this.#escapeHandler = null;
    }
    this.#controller = null;
    this.#rightDownPosition = null;
    this.#hasDragged = false;
  }

  /**
   * Remove every ghost sprite from the controls layer
   */
  static clearGraphics() {
    if (!canvas?.controls?.children) return;
    try {
      for (const child of Array.from(canvas.controls.children)) {
        if (!child._flashTokenBarTeleportPreview) continue;
        canvas.controls.removeChild(child);
        child.destroy?.();
      }
    } catch (error) {
      LogUtil.warn("TokenTeleportPreview: error clearing preview graphics", [error]);
    }
    this.#rightDownPosition = null;
  }

  /**
   * Cursor position in token layer coordinates
   * @param {PIXI.FederatedPointerEvent} event
   * @returns {{x: number, y: number}}
   */
  static localPosition(event) {
    const position = event.getLocalPosition ? event.getLocalPosition(canvas.tokens) : event.data.getLocalPosition(canvas.tokens);
    return { x: position.x, y: position.y };
  }

  /**
   * Snap a point to half grid intervals
   * @param {number} x
   * @param {number} y
   * @returns {{x: number, y: number}}
   */
  static snapToHalfGrid(x, y) {
    const halfGrid = canvas.grid.size / 2;
    return {
      x: Math.round(x / halfGrid) * halfGrid,
      y: Math.round(y / halfGrid) * halfGrid
    };
  }

  /**
   * Draw ghost sprites at the given placements
   * @param {Array<{src: string, x: number, y: number, width: number, height: number}>} placements
   * @returns {Promise<void>}
   */
  static async draw(placements) {
    this.clearGraphics();
    if (!canvas?.controls) return;
    try {
      for (const placement of placements) {
        const texture = await foundry.canvas.loadTexture(placement.src);
        const ghost = new PIXI.Sprite(texture);
        ghost.anchor.set(0);
        ghost.x = placement.x;
        ghost.y = placement.y;
        ghost.width = placement.width;
        ghost.height = placement.height;
        ghost.alpha = 0.5;
        ghost.tint = 0x00ccff;
        ghost._flashTokenBarTeleportPreview = true;
        canvas.controls.addChild(ghost);
      }
    } catch (error) {
      LogUtil.warn("TokenTeleportPreview: error drawing preview", [error]);
    }
  }

  /**
   * Track right-button drags and redraw the ghosts under the cursor
   * @param {PIXI.FederatedPointerEvent} event
   */
  static #onMouseMove(event) {
    const position = this.localPosition(event);
    if (this.#rightDownPosition) {
      const distance = Math.hypot(position.x - this.#rightDownPosition.x, position.y - this.#rightDownPosition.y);
      if (distance > 5) this.#hasDragged = true;
    }
    const controller = this.#controller;
    if (!controller || controller.isPerformingTeleport() || !canvas?.controls) return;
    const snapped = this.snapToHalfGrid(position.x, position.y);
    const placements = controller.getPreviewPlacements(snapped);
    if (placements.length === 0) return;
    this.draw(placements);
  }

  /**
   * Place the tokens at the clicked point
   * @param {PIXI.FederatedPointerEvent} event
   * @returns {Promise<void>}
   */
  static async #onClick(event) {
    const controller = this.#controller;
    if (!controller || controller.isPerformingTeleport()) return;
    const position = this.localPosition(event);
    await controller.place(this.snapToHalfGrid(position.x, position.y));
  }

  /**
   * Cancel on a right-click that was not a canvas pan
   * @param {PIXI.FederatedPointerEvent} event
   */
  static #onRightClick(event) {
    const controller = this.#controller;
    if (!controller) return;
    if (this.#hasDragged) {
      LogUtil.log("TokenTeleportPreview: ignoring right-click after drag");
      return;
    }
    event.stopPropagation();
    controller.cancel();
  }

  /**
   * Remember where a right-button press started so drags can be told apart from clicks
   * @param {PIXI.FederatedPointerEvent} event
   */
  static #onRightDown(event) {
    this.#rightDownPosition = this.localPosition(event);
    this.#hasDragged = false;
  }

  /**
   * Forget the drag state shortly after the right button is released
   */
  static #onRightUp() {
    setTimeout(() => {
      this.#rightDownPosition = null;
      this.#hasDragged = false;
    }, 300);
  }

  /**
   * Cancel on Escape
   * @param {KeyboardEvent} event
   */
  static #onKeyDown(event) {
    if (event.key !== "Escape" || !this.#controller) return;
    event.preventDefault();
    event.stopPropagation();
    this.#controller.cancel();
  }
}
