import { getSettings } from "../constants/Settings.mjs";
import { SettingsUtil } from "../utils/SettingsUtil.mjs";

/**
 * Resolves the "uniqueId" used across the module (a token id in the current scene, or an actor id)
 * into actors, tokens and participant records.
 * @module actors/ActorResolver
 */

/**
 * @typedef {Object} Participant
 * @property {string} uniqueId - Token id when the entry is a placed token, otherwise the actor id
 * @property {string} actorId - Base actor id
 * @property {string|null} tokenId - Token document id in the current scene, if any
 * @property {Actor} actor - The actor (synthetic token actor for unlinked tokens)
 * @property {TokenDocument|null} tokenDoc
 * @property {string} name
 * @property {string} img
 */
export class ActorResolver {
  /**
   * Token document in the current scene for a unique id
   * @param {string} uniqueId
   * @returns {TokenDocument|null}
   */
  static getTokenDocument(uniqueId) {
    if (!uniqueId) return null;
    return game.scenes.current?.tokens.get(uniqueId) ?? canvas.tokens?.get(uniqueId)?.document ?? null;
  }

  /**
   * Actor for a unique id
   * @param {string} uniqueId
   * @returns {Actor|null}
   */
  static getActor(uniqueId) {
    if (!uniqueId) return null;
    const tokenDoc = this.getTokenDocument(uniqueId);
    if (tokenDoc?.actor) return tokenDoc.actor;
    return game.actors.get(uniqueId) ?? null;
  }

  /**
   * Whether a unique id refers to a token in the current scene
   * @param {string} uniqueId
   * @returns {boolean}
   */
  static isTokenId(uniqueId) {
    return !!this.getTokenDocument(uniqueId);
  }

  /**
   * Unique id for an actor / token pair
   * @param {Actor} actor
   * @param {TokenDocument|null} [tokenDoc]
   * @returns {string}
   */
  static getUniqueId(actor, tokenDoc = null) {
    return tokenDoc?.id ?? actor.id;
  }

  /**
   * Build a participant record from an actor and optional token
   * @param {Actor} actor
   * @param {TokenDocument|null} [tokenDoc]
   * @returns {Participant|null}
   */
  static participantFromActor(actor, tokenDoc = null) {
    if (!actor) return null;
    const sourceActor = tokenDoc?.actor ?? actor;
    return {
      uniqueId: this.getUniqueId(actor, tokenDoc),
      actorId: actor.id,
      tokenId: tokenDoc?.id ?? null,
      actor: sourceActor,
      tokenDoc: tokenDoc ?? null,
      name: tokenDoc?.name ?? actor.name,
      img: this.participantImage(actor, tokenDoc)
    };
  }

  /**
   * Row image according to the portrait source setting: the token texture, or the actor portrait
   * @param {Actor} actor
   * @param {TokenDocument|null} tokenDoc
   * @returns {string}
   */
  static participantImage(actor, tokenDoc) {
    const SETTINGS = getSettings();
    const useActor = SettingsUtil.get(SETTINGS.actorImageSource.tag) === "actor";
    if (useActor) return tokenDoc?.actor?.img ?? actor.img;
    return tokenDoc?.texture?.src ?? actor.img;
  }

  /**
   * Resolve one unique id into a participant
   * @param {string} uniqueId
   * @returns {Participant|null}
   */
  static resolveParticipant(uniqueId) {
    const tokenDoc = this.getTokenDocument(uniqueId);
    if (tokenDoc) {
      const baseActor = tokenDoc.actor ? (game.actors.get(tokenDoc.actorId) ?? tokenDoc.actor) : null;
      if (!baseActor) return null;
      return this.participantFromActor(baseActor, tokenDoc);
    }
    const actor = game.actors.get(uniqueId);
    return actor ? this.participantFromActor(actor, null) : null;
  }

  /**
   * Resolve many unique ids, skipping the ones that no longer exist
   * @param {Iterable<string>} uniqueIds
   * @returns {Participant[]}
   */
  static resolveParticipants(uniqueIds) {
    const participants = [];
    for (const uniqueId of uniqueIds ?? []) {
      const participant = this.resolveParticipant(uniqueId);
      if (participant) participants.push(participant);
    }
    return participants;
  }

  /**
   * Placed tokens in the current scene for an actor
   * @param {string} actorId
   * @returns {TokenDocument[]}
   */
  static getSceneTokens(actorId) {
    return game.scenes.current?.tokens.filter(token => token.actorId === actorId) ?? [];
  }

  /**
   * Canvas token object for a participant, if the scene is active
   * @param {Participant|{tokenId?: string, actorId?: string}} participant
   * @returns {Token|null}
   */
  static getCanvasToken(participant) {
    if (!canvas?.tokens) return null;
    if (participant.tokenId) {
      return canvas.tokens.get(participant.tokenId) ?? null;
    }
    return canvas.tokens.placeables.find(t => t.actor?.id === participant.actorId) ?? null;
  }

  /**
   * Whether an actor has at least one token in the current scene
   * @param {Actor} actor
   * @returns {boolean}
   */
  static hasTokenInScene(actor) {
    return this.getSceneTokens(actor.id).length > 0;
  }
}
