import { LANG_PREFIX } from "../constants/General.mjs";
import { LogUtil } from "../utils/LogUtil.mjs";
import { ActorResolver } from "../actors/ActorResolver.mjs";
import { TokenTeleportPreview } from "./TokenTeleportPreview.mjs";
import { TokenTeleportExecutor } from "./TokenTeleportExecutor.mjs";
import { NotifyUtil } from "../utils/NotifyUtil.mjs";

/**
 * Teleports tokens within a scene or across scenes, keeping their relative layout.
 * Interactive mode shows ghost previews on the canvas (TokenTeleportPreview); the API entry
 * point teleports straight to a destination. Document updates live in TokenTeleportExecutor.
 * @module tokens/TokenTeleport
 */
export class TokenTeleport {
  static #isTeleporting = false;
  static #isPerformingTeleport = false;
  /** @type {import("./TokenTeleportExecutor.mjs").TeleportTokenData[]} */
  static #tokenData = [];
  static #sourceScene = null;
  static #targetScene = null;

  /**
   * Enter interactive teleport mode for the tokens of the actors selected in the menu
   * @param {{selectedActors: Set<string>, currentTab: string}} menu
   * @returns {Promise<void>}
   */
  static async teleportSelectedTokens(menu) {
    if (menu.selectedActors.size === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noTokensSelectedForTeleport`));
      return;
    }
    if (this.#isTeleporting) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.teleportInProgress`));
      return;
    }

    const tokenData = this.#collectTokenData(menu.selectedActors);
    if (tokenData.length === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noTokensSelectedForTeleport`));
      return;
    }

    this.#tokenData = tokenData;
    this.#sourceScene = canvas.scene;
    this.#targetScene = canvas.scene;
    this.#isTeleporting = true;
    this.#enterPlacementMode(true);
  }

  /**
   * Teleport tokens to a scene and location without user interaction
   * @param {string[]} uniqueIds - Token ids (or actor ids resolved to their canvas token)
   * @param {string|Scene} destinationScene - Scene id, scene name or Scene
   * @param {{x: number, y: number}} centerLocation - Group center in the destination scene
   * @returns {Promise<void>}
   */
  static async teleportToDestination(uniqueIds, destinationScene, centerLocation) {
    await this.#waitForIdle();

    if (!uniqueIds?.length) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noTokensSelectedForTeleport`));
      return;
    }
    if (typeof centerLocation?.x !== "number" || typeof centerLocation?.y !== "number") {
      NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.invalidTeleportDestination`));
      return;
    }
    const targetScene = this.#resolveScene(destinationScene);
    if (!targetScene) return;
    if (!game.user.isGM && targetScene.id !== canvas.scene?.id) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.gmOnlyTeleport`));
      return;
    }

    const tokenData = this.#collectTokenData(uniqueIds);
    if (tokenData.length === 0) {
      NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.noValidTokensForTeleport`));
      return;
    }
    if (tokenData.length < uniqueIds.length) {
      NotifyUtil.warn(game.i18n.format(`${LANG_PREFIX}.notifications.someTokensSkippedForTeleport`, { count: tokenData.length }));
    }

    this.#tokenData = tokenData;
    this.#sourceScene = canvas.scene;
    this.#targetScene = targetScene;
    this.#isTeleporting = true;
    this.#isPerformingTeleport = true;

    const snapped = targetScene.grid.getSnappedPoint(centerLocation, { mode: CONST.GRID_SNAPPING_MODES.CENTER });
    let teleportedIds = [];
    try {
      if (targetScene.id !== canvas.scene.id) {
        await targetScene.view();
      }
      teleportedIds = await this.#executeTeleport(snapped);
    } catch (error) {
      LogUtil.error("TokenTeleport: error during teleportation", [error]);
      this.#cleanup();
      throw error;
    }
    await TokenTeleportExecutor.focus(teleportedIds);
  }

  /**
   * Whether interactive teleport mode is active
   * @returns {boolean}
   */
  static isTeleporting() {
    return this.#isTeleporting;
  }

  /**
   * Whether a teleport is being executed right now
   * @returns {boolean}
   */
  static isPerformingTeleport() {
    return this.#isPerformingTeleport;
  }

  /**
   * Re-enter placement mode on the newly viewed scene. Called from canvasReady.
   */
  static onSceneChange() {
    if (!this.#isTeleporting || this.#isPerformingTeleport) return;
    if (this.#targetScene?.id === canvas.scene?.id) return;
    this.#targetScene = canvas.scene;
    LogUtil.log("TokenTeleport: scene changed during teleport", [canvas.scene?.name]);
    TokenTeleportPreview.detach();
    TokenTeleportPreview.clearGraphics();
    setTimeout(() => this.#enterPlacementMode(false), 100);
  }

  /**
   * Leave teleport mode without moving anything
   */
  static cancel() {
    if (!this.#isTeleporting) return;
    LogUtil.log("TokenTeleport: cancelled");
    this.#cleanup();
    NotifyUtil.info(game.i18n.localize(`${LANG_PREFIX}.notifications.teleportCancelled`));
  }

  /**
   * Execute the teleport at a point picked on the canvas
   * @param {{x: number, y: number}} destination
   * @returns {Promise<void>}
   */
  static async place(destination) {
    if (!this.#isTeleporting || this.#isPerformingTeleport) return;
    if (!game.user.isGM && this.#targetScene?.id !== this.#sourceScene?.id) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.gmOnlyTeleport`));
      this.#cleanup();
      return;
    }
    this.#isPerformingTeleport = true;
    try {
      const teleportedIds = await this.#executeTeleport(destination);
      if (teleportedIds.length > 0) {
        NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.tokensTeleported`, { count: teleportedIds.length }));
      }
    } catch (error) {
      LogUtil.error("TokenTeleport: failed to teleport tokens", [error]);
      NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.teleportFailed`));
      this.#cleanup();
    }
  }

  /**
   * Ghost sprite placements for a cursor position on the current canvas
   * @param {{x: number, y: number}} point
   * @returns {import("./TokenTeleportExecutor.mjs").TeleportPlacement[]}
   */
  static getPreviewPlacements(point) {
    if (!this.#isTeleporting || !this.#targetScene) return [];
    return TokenTeleportExecutor.computePlacements(this.#tokenData, this.#sourceScene, point, this.#targetScene, false);
  }

  /**
   * Capture the token data needed to teleport a set of unique ids
   * @param {Iterable<string>} uniqueIds
   * @returns {import("./TokenTeleportExecutor.mjs").TeleportTokenData[]}
   */
  static #collectTokenData(uniqueIds) {
    const result = [];
    const seen = new Set();
    for (const uniqueId of uniqueIds) {
      const participant = ActorResolver.resolveParticipant(uniqueId);
      const token = participant ? ActorResolver.getCanvasToken(participant) : null;
      if (!token) {
        LogUtil.warn("TokenTeleport: no canvas token for id", [uniqueId]);
        continue;
      }
      if (seen.has(token.id)) continue;
      seen.add(token.id);
      result.push({
        id: token.id,
        sceneId: canvas.scene.id,
        x: token.document.x,
        y: token.document.y,
        width: token.document.width,
        height: token.document.height,
        src: token.document.texture.src,
        documentData: token.document.toObject()
      });
    }
    return result;
  }

  /**
   * Resolve a scene argument, notifying on failure
   * @param {string|Scene} destinationScene
   * @returns {Scene|null}
   */
  static #resolveScene(destinationScene) {
    if (destinationScene instanceof Scene) return destinationScene;
    if (typeof destinationScene === "string") {
      const scene = game.scenes.get(destinationScene) || game.scenes.getName(destinationScene);
      if (scene) return scene;
      NotifyUtil.error(game.i18n.format(`${LANG_PREFIX}.notifications.sceneNotFound`, { scene: destinationScene }));
      return null;
    }
    NotifyUtil.error(game.i18n.localize(`${LANG_PREFIX}.notifications.invalidTeleportDestination`));
    return null;
  }

  /**
   * Wait until a running teleport finishes
   * @returns {Promise<void>}
   */
  static #waitForIdle() {
    if (!this.#isPerformingTeleport) return Promise.resolve();
    LogUtil.log("TokenTeleport: teleport in progress, queueing");
    return new Promise(resolve => {
      const interval = setInterval(() => {
        if (this.#isPerformingTeleport) return;
        clearInterval(interval);
        resolve();
      }, 50);
    });
  }

  /**
   * Fade source tokens on the canvas, attach preview handlers and notify
   * @param {boolean} showNotification
   */
  static #enterPlacementMode(showNotification) {
    if (this.#targetScene.id === this.#sourceScene.id) {
      for (const token of this.#getCanvasTokens()) token.alpha = 0.5;
    }
    TokenTeleportPreview.attach(this);
    LogUtil.log("TokenTeleport: ready", [this.#tokenData.length, this.#targetScene.name]);
    if (showNotification) {
      NotifyUtil.info(game.i18n.format(`${LANG_PREFIX}.notifications.teleportReady`, { count: this.#tokenData.length }));
    }
  }

  /**
   * Canvas token objects for the captured data that are on the current canvas
   * @returns {Token[]}
   */
  static #getCanvasTokens() {
    return this.#tokenData
      .filter(data => data.sceneId === canvas.scene?.id)
      .map(data => canvas.tokens.get(data.id))
      .filter(token => !!token);
  }

  /**
   * Drop tokens that vanished from the source scene, run the executor and clean up
   * @param {{x: number, y: number}} destination
   * @returns {Promise<string[]>} Ids of the teleported tokens
   */
  static async #executeTeleport(destination) {
    const sourceScene = this.#sourceScene;
    const targetScene = this.#targetScene;
    this.#tokenData = this.#tokenData.filter(data => !!sourceScene.tokens.get(data.id));
    if (this.#tokenData.length === 0) {
      NotifyUtil.warn(game.i18n.localize(`${LANG_PREFIX}.notifications.noValidTokensForTeleport`));
      this.#cleanup();
      return [];
    }
    const teleportedIds = await TokenTeleportExecutor.execute(this.#tokenData, sourceScene, targetScene, destination);
    this.#cleanup();
    return teleportedIds;
  }

  /**
   * Restore canvas tokens, remove previews and reset state
   */
  static #cleanup() {
    for (const token of this.#getCanvasTokens()) token.alpha = 1;
    TokenTeleportPreview.detach();
    TokenTeleportPreview.clearGraphics();
    this.#isTeleporting = false;
    this.#isPerformingTeleport = false;
    this.#tokenData = [];
    this.#sourceScene = null;
    this.#targetScene = null;
  }
}
