/**
 * Derives stat and resource definitions from an actor's prototype token bars, falling back to the
 * first trackable bar attribute the system declares. Works in any system because Foundry requires
 * every actor type to expose trackable attributes.
 * @module adapters/generic/BarAttributeStats
 */
export class BarAttributeStats {
  /**
   * Resource definitions for the actor's bars, or the first trackable bar attribute when none is configured
   * @param {Actor} actor
   * @returns {import("../../core/Capabilities.mjs").ResourceDef[]}
   */
  static getResources(actor) {
    const resources = [];
    const seen = new Set();
    for (const attribute of this.candidateAttributes(actor)) {
      if (seen.has(attribute)) continue;
      const def = this.#resourceFromAttribute(actor, attribute, `bar${resources.length + 1}`);
      if (!def) continue;
      seen.add(attribute);
      resources.push(def);
      if (resources.length === 2) break;
    }
    return resources;
  }

  /**
   * Stats shown next to the actor name: the bar resources as value/max
   * @param {Actor} actor
   * @returns {import("../../core/Capabilities.mjs").StatDef[]}
   */
  static getStatsList(actor) {
    return this.getResources(actor).map(resource => ({
      abbrev: resource.label,
      path: resource.currentValuePath,
      maxPath: resource.maxValuePath,
      showMax: true
    }));
  }

  /**
   * Attribute paths to try, in order: configured token bars, then the system's trackable bar attributes
   * @param {Actor} actor
   * @returns {string[]}
   */
  static candidateAttributes(actor) {
    const configured = [];
    for (const barName of ["bar1", "bar2"]) {
      const attribute = actor?.prototypeToken?.[barName]?.attribute;
      if (attribute) configured.push(attribute);
    }
    const trackable = [...this.trackableBarAttributes(actor)].sort((a, b) => this.#priority(a) - this.#priority(b));
    return [...configured, ...trackable];
  }

  /**
   * Lower is better: health-like attributes first, encumbrance-like attributes last
   * @param {string} attribute
   * @returns {number}
   */
  static #priority(attribute) {
    const key = attribute.toLowerCase();
    if (/(^|\.)(hp|health|hitpoints|hit_points|wounds?|vitality|life)($|\.)/.test(key)) return 0;
    if (/(stamina|stress|sanity|mana|power|spell|magic|energy|focus|resolve)/.test(key)) return 1;
    if (/(encumbrance|weight|carry|load|capacity|movement|speed|exp|xp)/.test(key)) return 3;
    return 2;
  }

  /**
   * Bar attributes the system declares as trackable for the actor's type
   * @param {Actor} actor
   * @returns {string[]}
   */
  static trackableBarAttributes(actor) {
    const configured = CONFIG.Actor?.trackableAttributes?.[actor?.type]?.bar;
    if (Array.isArray(configured) && configured.length > 0) return configured;
    const TokenDocumentClass = foundry.documents?.TokenDocument ?? globalThis.TokenDocument;
    try {
      const tracked = TokenDocumentClass?.getTrackedAttributes?.(actor?.system ?? {});
      return (tracked?.bar ?? []).map(path => Array.isArray(path) ? path.join(".") : String(path));
    } catch (error) {
      return [];
    }
  }

  /**
   * Build a resource definition from a system attribute path
   * @param {Actor} actor
   * @param {string} attribute - Path inside actor.system, e.g. "attributes.hp"
   * @param {string} id
   * @returns {import("../../core/Capabilities.mjs").ResourceDef|null}
   */
  static #resourceFromAttribute(actor, attribute, id) {
    const data = foundry.utils.getProperty(actor?.system ?? {}, attribute);
    if (data === undefined || data === null) return null;
    const isBar = typeof data === "object" && "value" in data && "max" in data;
    if (!isBar) return null;
    return {
      id,
      label: this.labelFromPath(attribute),
      currentValuePath: `system.${attribute}.value`,
      maxValuePath: `system.${attribute}.max`,
      usageTracking: false
    };
  }

  /**
   * Human readable label from an attribute path, e.g. "attributes.hp" -> "HP", "resources.stress" -> "Stress"
   * @param {string} path
   * @returns {string}
   */
  static labelFromPath(path) {
    const last = path.split(".").pop() ?? path;
    if (last.length <= 3) {
      return last.toUpperCase();
    }
    return last.charAt(0).toUpperCase() + last.slice(1);
  }
}
